function transform(ctx) {
  var p = ctx.vars.portal_path || "";
  if (!p || p.indexOf("?") < 0) throw new Error("未能获取门户跳转地址，请核对本校门户地址后把地址写进本步骤脚本");
  var q = p.slice(p.indexOf("?") + 1);
  return { eu: url_encode(ctx.username || ""), ep: url_encode(ctx.password || ""), es: url_encode(""), qse: url_encode(url_encode(q)) }; // 原实现 login.py L159 quote(query_string, safe="")，requests data= 提交时再整体编码一次 => 双重编码
}
